/** Web-search tool calls generated by Vex's JSON "action" field. */

const enc = (query) => encodeURIComponent(String(query).trim())

/** Every platform Vex can open, with the aliases the model may emit. */
export const PLATFORMS = {
  youtube: {
    aliases: ['youtube', 'yt'],
    url: (q) => `https://www.youtube.com/results?search_query=${enc(q)}`,
  },
  facebook: {
    aliases: ['facebook', 'fb'],
    url: (q) => `https://www.facebook.com/search/top?q=${enc(q)}`,
  },
  tiktok: {
    aliases: ['tiktok', 'tt'],
    url: (q) => `https://www.tiktok.com/search?q=${enc(q)}`,
  },
  instagram: {
    aliases: ['instagram', 'ig'],
    url: (q) => `https://www.instagram.com/explore/search/keyword/?q=${enc(q)}`,
  },
  x: {
    aliases: ['x', 'twitter', 'x.com'],
    url: (q) => `https://x.com/search?q=${enc(q)}`,
  },
  reddit: {
    aliases: ['reddit'],
    url: (q) => `https://www.reddit.com/search/?q=${enc(q)}`,
  },
  google: {
    aliases: ['google', 'web', 'internet'],
    url: (q) => `https://www.google.com/search?q=${enc(q)}`,
  },
  github: {
    aliases: ['github', 'gh'],
    url: (q) => `https://github.com/search?q=${enc(q)}`,
  },
  spotify: {
    aliases: ['spotify'],
    url: (q) => `https://open.spotify.com/search/${enc(q)}`,
  },
  linkedin: {
    aliases: ['linkedin'],
    url: (q) => `https://www.linkedin.com/search/results/all/?keywords=${enc(q)}`,
  },
  chatgpt: {
    aliases: ['chatgpt', 'chat gpt', 'gpt', 'openai', 'chat openai'],
    url: (q) => `https://chatgpt.com/?q=${enc(q)}`,
  },
}

export const PLATFORM_IDS = Object.keys(PLATFORMS)

const PLATFORM_LABELS = {
  youtube: 'YouTube',
  facebook: 'Facebook',
  tiktok: 'TikTok',
  instagram: 'Instagram',
  x: 'X',
  reddit: 'Reddit',
  google: 'Google',
  github: 'GitHub',
  spotify: 'Spotify',
  linkedin: 'LinkedIn',
  chatgpt: 'ChatGPT',
}

export function platformLabel(platform) {
  const id = normalizePlatform(platform)
  return id ? PLATFORM_LABELS[id] : String(platform || 'site')
}

/** Map any alias ("fb", "twitter", "IG"...) to its canonical platform id. */
export function normalizePlatform(value) {
  const raw = String(value || '')
    .trim()
    .toLowerCase()
    .replace(/\.com$/, '')
  for (const id of PLATFORM_IDS) {
    if (id === raw || PLATFORMS[id].aliases.includes(raw)) return id
  }
  return null
}

const escapeRegex = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

const ALIAS_PATTERN = new RegExp(
  `\\b(${PLATFORM_IDS.flatMap((id) => [id, ...PLATFORMS[id].aliases])
    .filter(Boolean)
    .map(escapeRegex)
    .sort((a, b) => b.length - a.length)
    .join('|')})\\b`,
  'i',
)

export function detectSearchIntent(text) {
  const value = String(text || '')
  const match = value.match(ALIAS_PATTERN)
  if (!match) return null
  if (!/\b(hanapin|search|i-search|patingin|tingnan|buksan|open|find|look|show|check|tutorial|video|meme|post|tweet|reel|track|song|repo)\b/i.test(value)) {
    return null
  }
  return normalizePlatform(match[1])
}

/** Fallback when the LLM is rate-limited: read the request straight from the user's words. */
export function localSearchAction(text) {
  const platform = detectSearchIntent(text)
  if (!platform) return null
  const query = String(text || '')
    .replace(/^\s*(vex\s*,?\s*)?(i-search\s+mo|hanapin\s+mo|patingin\s+nga|patingin|buksan\s+mo|tingnan\s+mo|open|find|search\s+for|search)\b/gi, ' ')
    .replace(/\b(youtube|yt|facebook|fb|tiktok|tt|instagram|ig|twitter|x\.com|reddit|google|github|spotify|linkedin|chatgpt|chat\s*gpt|gpt|openai)\b/gi, ' ')
    .replace(/^\s*(sa|ng|ung|yung|ang|ko|mo|na|lang)\b/gi, ' ')
    .replace(/[?.!,]+$/g, '')
    .replace(/\s+/g, ' ')
    .trim()
  return query ? { platform, query: query.slice(0, 200) } : null
}

export function buildSearchUrl({ platform, query }) {
  const term = String(query || '').trim()
  if (!term) return null
  const id = normalizePlatform(platform)
  return id ? PLATFORMS[id].url(term) : null
}

/** Open a blank tab during the user's click gesture to avoid popup blocking. */
export function preopenTab() {
  try {
    if (typeof window === 'undefined') return null
    return window.open('about:blank', 'vexSearchTab')
  } catch {
    return null
  }
}

/** Navigate the pre-opened tab (or open a new one) to the search results. */
export function runWebAction(action, tab = null) {
  const url = buildSearchUrl(action)
  if (!url) return false
  try {
    // Reuse the named tab opened during the user's click. Assigning to a
    // WindowProxy's location can throw; opening the same target name navigates
    // it without touching a cross-origin object.
    const win = window.open(url, tab && !tab.closed ? 'vexSearchTab' : '_blank')
    // ChatGPT may not honour ?q= on every version. Copy the prompt too, so a
    // paste into the composer is always one keystroke away.
    if (normalizePlatform(action?.platform) === 'chatgpt' && action?.query) {
      try {
        navigator.clipboard?.writeText(String(action.query))
      } catch {
        /* clipboard permission is optional */
      }
    }
    return Boolean(win) || Boolean(tab && !tab.closed)
  } catch {
    return false
  }
}


